itemIll=(old=>function(cat,o){try{o=o||{};if(o.g){const r=v6Gear(o);if(r)return r;}else if(o.car||cat==='arac')return v6Car(o);else if(cat==='krampon')return v6Boot(o);else if(cat==='ev')return v6House(o);else if(cat==='stil'&&V6I[o.t])return v6Pack(V6I[o.t],o);}catch(e){}return old.apply(this,arguments);})(itemIll);

