SHOP_DR.hakem.items.push(['ref_duduk','Profesyonel düdük','Net ve güçlü ses.',E6(30),0,2,{g:'duduk'}],['ref_kart','Kart ve maç notu cüzdanı','Düzenli maç notları.',E6(40),0,2,{g:'kart'}],['ref_kosu','Koşu ayakkabısı','Hafif ve yaylı taban.',E6(160),0,2,{g:'sneaker',c:'#16181c',a:'#d7ff3a'}],['ref_kalp','Nabız göğüs bandı','Kondisyon takibi: gözlemci notun +0,05.',E6(120),0,2,{g:'kalp'}]);

/* ---------- 4) görünürlük, sıralama, satın alma ---------- */
function v160Find(k){for(const SH of [SHOP,SHOP_TD,SHOP_YRD,SHOP_SC,SHOP_DR])for(const [ck,cc] of Object.entries(SH)){const f=cc.items.find(x=>x[0]===k);if(f)return {it:f,cat:ck};}return null;}
function v160Vis(it){try{const o=it[6]||{},p=G.p;if(o.age&&p.age<o.age)return false;if(o.pos&&!(p.pos===o.pos||p.spos===o.pos))return false;if(o.role&&!(isRole()&&G.m.role===o.role))return false;return true;}catch(e){return true;}}
shopFor=(old=>function(){let o=old.apply(this,arguments);try{o=Object.assign({},o);const pl=isPl(),age=G.p.age;
  if(pl){const ord=['krampon','ekipman','toparlanma','ekip','stil','arac','ev','lux'],n={};for(const k of ord)if(o[k])n[k]=o[k];for(const k in o)if(!n[k])n[k]=o[k];o=n;if(age<18)delete o.lux;}
  else{if(!o.kiyafet)o.kiyafet=SHOP_TD.kiyafet;if(age>=18)o.lux=SHOP.lux;if(isRole()){delete o.kenar;}else delete o.yonetim;if(!isRole()&&G.mode==='mgr'){}}
  for(const k of Object.keys(o))if(o[k]&&o[k].items&&!o[k].items.some(v160Vis))delete o[k];}catch(e){}return o;})(shopFor);
buyItem=(old=>function(cat,k){const F=v160Find(k);try{if(F&&!v160Vis(F.it)){const o=F.it[6]||{};return toast(o.age?`Bu ürün için ${o.age} yaşını doldurmalısın`:'Bu ürün senin için uygun değil');}}catch(e){}
  const p=G.p,had=!!(p&&p.up&&p.up[k]);const r=old.apply(this,arguments);
  try{if(!had&&p.up[k]&&F){if(F.cat==='krampon'&&F.it[6]&&F.it[6].c)p.up.kc=F.it[6].c;
    if(F.cat==='ev'){let mf=0;for(const h in V160_EV)if(p.up[h])mf=Math.max(mf,V160_EV[h]);p.up.mfloor=mf;}save();render();}}catch(e){}return r;})(buyItem);
ACTX.v160giy=el=>{const F=v160Find(el.dataset.k);if(!F||!G.p.up[el.dataset.k])return;G.p.up.kc=F.it[6].c;save();render();toast(`${F.it[1]} ayağında`);};
const v160KT=['','Standart','Hız','Pro','Elit'];
function v160List(SH){const p=G.p,cat=SH[SHOPC];if(!cat)return null;const isB=SHOPC==='krampon',items=cat.items.filter(v160Vis);
  const head=isB?`<p class="muted v160-nt">Maçta ayağında giydiğin model görünür; isabet etkisi sahip olduğun en iyi seriden gelir (en iyi: ${v160KT[p.up.kt||0]||'yok'}).</p>`:'';
  return head+`<ul class="shop2 v160s">${items.map(([k,n,d,c,f,m,o])=>{const own=!!p.up[k];let act;
    if(own)act=isB?(p.up.kc&&o&&p.up.kc===o.c?'<span class="pill good">Ayağında</span>':`<button class="btn ghost" data-act="v160giy" data-k="${k}">Giy</button>`):'<span class="pill good">Sahipsin</span>';
    else act=`<button class="btn" data-act="buy2" data-c="${SHOPC}" data-k="${k}" ${p.money<c?'disabled':''}>${money(c)}</button>`;
    return `<li class="${own?'own':''}">${itemIll(SHOPC,o||{})}<div class="si"><b>${n}</b><p>${d}</p><small>${isB&&o?`${v160KT[o.t]||''} seri · `:''}${f?`Şöhret +${f} · `:''}Moral +${m}</small></div>${act}</li>`;}).join('')}</ul>`;}
viewLife2=(old=>function(){const h=old.apply(this,arguments);try{if(typeof h==='string'&&h.indexOf('<ul class="shop2">')>=0){const SH=shopFor(),L=v160List(SH);if(L){const i=h.indexOf('<ul class="shop2">'),j=h.indexOf('</ul>',i);if(j>i)return h.slice(0,i)+L+h.slice(j+5);}}}catch(e){}return h;})(viewLife2);
/* etkiler */
const v160Up=k=>!!(G&&G.p&&G.p.up&&G.p.up[k]);
shopOnBuy=(old=>function(key){old.apply(this,arguments);try{const rep=(n)=>{if(G.mode==='mgr'&&G.m)G.m.rep=clamp((G.m.rep||30)+n,0,100);else if(G.job)G.job.rep=clamp((G.job.rep||0)+n,0,100);};
  if(key==='td_seminer')rep(3);if(key==='sd_veri')rep(2);if(key==='sd_ag')rep(3);if(key==='bsk_gala')rep(4);if(key==='sc_not'||key==='dr_canta')rep(2);
  if(key==='yr_tablet'&&G.job)G.job.tr=clamp((G.job.tr||50)+3,0,100);}catch(e){}})(shopOnBuy);
rollInjury=(old=>function(){const r=old.apply(this,arguments);try{if(r&&isPl()&&r.days){const red=Math.min(0.25,(v160Up('pl_tek')?0.05:0)+(v160Up('pl_komp')?0.05:0)+(v160Up('pl_besin')?0.05:0)+(v160Up('pl_yoga')?0.05:0)+(v160Up('pl_kriyo')?0.1:0));if(red>0)r.days=Math.max(2,Math.round(r.days*(1-red)));}}catch(e){}return r;})(rollInjury);
nextDay=(old=>function(){const r=old.apply(this,arguments);try{if(isPl()&&G.p&&!G.p.injury){const b=Math.min(2,['pl_masaj','pl_uyku','pl_buz','pl_bot'].filter(v160Up).length*0.5);if(b)G.p.energy=clamp(G.p.energy+b,0,100);}}catch(e){}return r;})(nextDay);
gainAttr=(old=>function(k,v){if(G&&G.p&&isPl()&&v160Up('pl_saat'))v*=1.05;return old.call(this,k,v);})(gainAttr);
relWeek=(old=>function(){const r=old.apply(this,arguments);try{const m=G.m;if(m&&m.fm){const b=(v160Up('td_laptop')?0.5:0)+(v160Up('td_kitap')?0.5:0);if(b)m.fm.fam=Math.min(100,m.fm.fam+b);}}catch(e){}return r;})(relWeek);
try{refFinish=(old=>function(){try{if(REF&&v160Up('ref_kalp'))REF.rt+=.05;}catch(e){}return old.apply(this,arguments);})(refFinish);}catch(e){}
